    public constructor(props: IProps) {
        super(props);

        this.supportsRestricted = !!this.props.parentSpace;

        let joinRule = JoinRule.Invite;
        if (this.props.defaultPublic) {
            joinRule = JoinRule.Public;
        } else if (this.supportsRestricted) {
            joinRule = JoinRule.Restricted;
        }

        const cli = MatrixClientPeg.safeGet();
        this.state = {
            isPublic: this.props.defaultPublic || false,
            isEncrypted: this.props.defaultEncrypted ?? privateShouldBeEncrypted(cli),
            joinRule,
            name: this.props.defaultName || "",
            topic: "",
            alias: "",
            detailsOpen: false,
            noFederate: SdkConfig.get().default_federate === false,
            nameIsValid: false,
            canChangeEncryption: true,
        };

        checkUserIsAllowedToChangeEncryption(cli, Preset.PrivateChat).then((result) => {
            const newState: Partial<IState> = { canChangeEncryption: result.allowChange };
            if (result.forcedValue !== undefined) {
                newState.isEncrypted = result.forcedValue;
            }
            this.setState(newState);
        });
    }
