            noFederate: SdkConfig.get().default_federate === false,
            nameIsValid: false,
            canChangeEncryption: true,
        };

        // Check encryption policies and update state accordingly
        checkUserIsAllowedToChangeEncryption(cli, Preset.PrivateChat).then((result) => {
            let isEncrypted = this.props.defaultEncrypted ?? privateShouldBeEncrypted(cli);

            // If there's a forced value, use it
            if (result.forcedValue !== undefined) {
                isEncrypted = result.forcedValue;
            }

            this.setState({
                canChangeEncryption: result.allowChange,
                forcedEncryptionValue: result.forcedValue,
                isEncrypted,
            });
        });
    }
