cat > /app/src/components/views/dialogs/CreateRoomDialog.tsx << 'EOF'
/*
Copyright 2017 Michael Telatynski <7t3chguy@gmail.com>
Copyright 2020, 2021 The Matrix.org Foundation C.I.C.

