cat > /tmp/new_code.txt << 'EOF'
import { shouldForceDisableEncryption } from "./utils/room/shouldForceDisableEncryption";

export interface AllowedEncryptionSetting {
    allowChange: boolean;
    forcedValue?: boolean;
}

/**
 * Checks if the user can change encryption configuration based on server and well-known configurations.
 *
 * This helper evaluates both sources of truth:
 * - The server-side policy (via the client's "does server force encryption for this preset?" capability)
 * - The .well-known policy (force_disable flag)
 *
 * When policies conflict, the server policy takes precedence.
 *
 * @param client The Matrix Client instance
 * @param chatPreset The room preset (e.g., Preset.PrivateChat)
 * @returns A promise resolving to an object indicating whether encryption can be changed and any forced value
 */
export async function checkUserIsAllowedToChangeEncryption(
    client: MatrixClient,
    chatPreset: Preset,
): Promise<AllowedEncryptionSetting> {
    // Check server policy first - it takes precedence
    const serverForcesEncryption = await client.doesServerForceEncryptionForPreset(chatPreset);
    if (serverForcesEncryption) {
        return {
            allowChange: false,
            forcedValue: true,
        };
    }

    // Check well-known policy for force_disable
    if (shouldForceDisableEncryption(client)) {
        return {
            allowChange: false,
            forcedValue: false,
        };
    }

    // Neither policy forces a value, so changes are allowed
    return {
        allowChange: true,
    };
}
